"use client";

import { useState } from "react";
import Link from "next/link";
import { useAuth } from "../context/AuthContext";
import IntroExperience from "@/components/intro/IntroExperience";
import CursorGlow from "@/components/CursorGlow";
import Nav from "@/components/Nav";
import Hero from "@/components/Hero";
import Marquee from "@/components/Marquee";
import About from "@/components/About";
import Cocktails from "@/components/Cocktails";
import Gallery from "@/components/Gallery";
import Nights from "@/components/Nights";
import Testimonials from "@/components/Testimonials";
import Reservation from "@/components/Reservation";
import Footer from "@/components/Footer";

export default function Home() {
  const [introDone, setIntroDone] = useState(false);
  
  // Bring in the authentication logic
  const { user, isAdmin, loading, signInWithGoogle, signOut } = useAuth();

  return (
    <>
      {!introDone && <IntroExperience onFinish={() => setIntroDone(true)} />}
      <CursorGlow />
      
      {/* --- DYNAMIC AUTH TOP BAR --- */}
      <div className="relative z-50 w-full bg-obsidian flex justify-end items-center px-6 py-2 border-b border-gold/10 gap-6">
        {!loading && (
          <>
            {/* Show Admin Panel link ONLY if the user is an admin */}
            {isAdmin && (
              <Link
                href="/admin/dashboard"
                className="text-[10px] text-gold-bright hover:text-cream uppercase tracking-[0.2em] transition-colors"
              >
                Admin Panel
              </Link>
            )}

            {/* Toggle Sign In / Sign Out */}
            {user ? (
              <button
                onClick={() => signOut()}
                className="text-[10px] text-smoke hover:text-red-400 uppercase tracking-[0.2em] transition-colors"
              >
                Sign Out
              </button>
            ) : (
              <button
                onClick={() => signInWithGoogle()}
                className="text-[10px] text-cream hover:text-gold uppercase tracking-[0.2em] transition-colors"
              >
                Sign In
              </button>
            )}
          </>
        )}
      </div>
      {/* ----------------------------- */}

      <Nav />
      <main>
        <Hero />
        <Marquee />
        <About />
        <Cocktails />
        <Gallery />
        <Nights />
        <Testimonials />
        <Reservation />
      </main>
      <Footer />
    </>
  );
}